function closeModal(e){e&&(e.classList.remove("is-open"),document.querySelector(".modal-container-enzo.is-open")||(document.body.style.overflow=""))}document.addEventListener("click",(function(e){const o=e.target.closest(".icone-editar-post");if(o){const e=o.getAttribute("data-modal-target"),t=document.getElementById(e);t&&(t.classList.add("is-open"),document.body.style.overflow="hidden")}if(e.target.classList.contains("close-modal")){closeModal(e.target.closest(".modal-container-enzo"))}e.target.classList.contains("modal-container-enzo")&&closeModal(e.target)})),document.addEventListener("keydown",(function(e){if("Escape"===e.key){const e=document.querySelector(".modal-container-enzo.is-open");e&&closeModal(e)}}));